using Vitarish.Communications.Contracts.Errors;
namespace Vitarish.Communications.Contracts.Results;
public enum CommunicationsCommandStatus { Accepted, Queued, Duplicate, ValidationFailure, Unauthorized, Forbidden, ProviderUnavailable, ProviderRejected, Timeout, Cancellation, UnexpectedFailure }
public sealed record CommunicationsCommandResult(CommunicationsCommandStatus Status, string? MessageId = null, CommunicationsError? Error = null, ProviderFailurePayload? ProviderFailure = null) { public bool IsSuccess => Status is CommunicationsCommandStatus.Accepted or CommunicationsCommandStatus.Queued; public static CommunicationsCommandResult Accepted(string? messageId=null)=>new(CommunicationsCommandStatus.Accepted,messageId); public static CommunicationsCommandResult Queued(string? messageId=null)=>new(CommunicationsCommandStatus.Queued,messageId); public static CommunicationsCommandResult Failed(CommunicationsCommandStatus status, CommunicationsError error, ProviderFailurePayload? providerFailure=null)=>new(status,null,error,providerFailure); }
public sealed record CommunicationsQueryResult<T>(T? Value, CommunicationsError? Error) { public bool IsSuccess => Error is null; public static CommunicationsQueryResult<T> Success(T value)=>new(value,null); public static CommunicationsQueryResult<T> Failed(CommunicationsError error)=>new(default,error); }
